mapper.select:
select `id`, `title`, `description`, `method`, `operator`, `ip`, `status`, `create_time`
from sys_oplog


        `status` = #{dto.status}


        and `operator` like concat('%',#{dto.operator},'%')


        and `create_time` >= #{dto.beginTime}
        and `create_time` <= #{dto.endTime}


order by `create_time` desc
